/**
 * SEO output integration test.
 *
 * Runs the real export pipeline (`buildSiteBundle`) over a small site and asserts on the
 * generated files: the 404 page and the redirect stubs. Like publicationBuild.integration.test,
 * only theme files, image preprocessing and merged theme config are mocked; the builders, the
 * renderer, navigation and URL generation are real.
 */
import type { LayoutManifest, LocalSiteData, ParsedMarkdownFile, ThemeManifest } from '@/core/types';

const THEME_MANIFEST: ThemeManifest = {
  name: 'starter',
  version: '1.0.0',
  files: [{ path: 'base.hbs', type: 'base' }],
  layouts: ['page'],
  stylesheets: [],
};

const LAYOUT_MANIFESTS: Record<string, LayoutManifest> = {
  page: { id: 'page', name: 'Page', version: '1.0.0', layoutType: 'page', parentLayout: 'base', files: [] },
};

const THEME_FILES: Record<string, string> = {
  'base.hbs':
    '<!DOCTYPE html><html><head><title>{{pageTitle}}</title>' +
    '{{#if headContext.noindex}}<meta name="robots" content="noindex">{{/if}}' +
    '<link rel="stylesheet" href="{{@root.options.relativeAssetPath}}_site/themes/starter/styles.css"></head>' +
    '<body><header><nav>{{#each navLinks}}<a href="{{href}}">{{label}}</a>{{/each}}</nav></header>' +
    '{{{body}}}<footer data-footer>Footer</footer></body></html>',
  'layouts/page/index.hbs': '<main data-layout="page">{{{content}}}</main>',
};

function resolveThemeAsset(assetPath: string): string | null {
  if (assetPath === 'theme.json') return JSON.stringify(THEME_MANIFEST);
  return THEME_FILES[assetPath] ?? null;
}

vi.mock('@/core/services/config/theme.service', () => ({
  getMergedThemeDataForForm: async (_name: string, config: Record<string, unknown>) => ({
    schema: null,
    initialConfig: config,
  }),
}));

vi.mock('@/core/services/config/configHelpers.service', () => ({
  clearAssetContentCache: () => {},
  getAssetContent: async (_context: unknown, _assetType: string, _assetId: string, fileName: string) =>
    resolveThemeAsset(fileName),
  getThemeAssetContent: async (_context: unknown, _themeName: string, assetPath: string) =>
    resolveThemeAsset(assetPath),
  getJsonAsset: async (_context: unknown, assetType: string) => (assetType === 'theme' ? THEME_MANIFEST : null),
  getLayoutManifest: async (_context: unknown, layoutId: string) => LAYOUT_MANIFESTS[layoutId] ?? null,
  getAvailableLayouts: async () => Object.values(LAYOUT_MANIFESTS),
}));

vi.mock('@/core/services/images/imagePreprocessor.service', () => ({
  imagePreprocessor: {
    preprocessImages: async () => {},
    getProcessedImageUrl: () => null,
    getProcessedMarkdownImageUrl: () => null,
    getProcessedImages: () => new Map(),
  },
}));

import { buildSiteBundle } from '../../siteBuilder.service';

function page(path: string, title: string, extra: Record<string, unknown> = {}, content = `${title} body`): ParsedMarkdownFile {
  return {
    path,
    slug: path.replace(/^content\//, '').replace(/\.md$/, ''),
    frontmatter: { title, layout: 'page', description: `About ${title}`, ...extra },
    content,
  };
}

function createSite(options: { baseUrl?: string; files?: ParsedMarkdownFile[] } = {}): LocalSiteData {
  const home = page('content/home.md', 'Home', { homepage: true });
  const about = page('content/about.md', 'About');
  const files = [home, about, ...(options.files ?? [])];
  return {
    siteId: 'seo-site',
    manifest: {
      siteId: 'seo-site',
      generatorVersion: '1.0.0',
      title: 'SEO Site',
      description: 'SEO site',
      ...(options.baseUrl ? { baseUrl: options.baseUrl } : {}),
      theme: { name: 'starter', config: {} },
      structure: files.map((file, index) => ({
        type: 'page' as const,
        title: file.frontmatter.title,
        slug: file.slug,
        path: file.path,
        navOrder: index + 1,
      })),
    },
    contentFiles: files,
  };
}

function dom(html: string): Document {
  return new DOMParser().parseFromString(html, 'text/html');
}

describe('404 page', () => {
  test('is generated by default with the theme header and footer, noindex, and root-absolute URLs', async () => {
    const bundle = await buildSiteBundle(createSite({ baseUrl: 'https://example.org' }));

    const html = bundle['404.html'] as string;
    expect(html).toBeDefined();
    const doc = dom(html);
    expect(doc.querySelector('title')?.textContent).toBe('Page not found');
    expect(doc.querySelector('header nav')).not.toBeNull();
    expect(doc.querySelector('[data-footer]')).not.toBeNull();
    expect(doc.querySelector('meta[name="robots"]')?.getAttribute('content')).toBe('noindex');
    expect(doc.querySelector('link[rel="stylesheet"]')?.getAttribute('href')).toBe('/_site/themes/starter/styles.css');
    expect(Array.from(doc.querySelectorAll('nav a')).map((a) => a.getAttribute('href'))).toEqual([
      '/index.html',
      '/about/index.html',
    ]);
    expect(doc.querySelector('main a')?.getAttribute('href')).toBe('/');
    // No URL may depend on the depth the visitor mistyped.
    expect(html).not.toMatch(/(?:href|src)="\.{1,2}\//);
  });

  test('keeps the hosting subpath for subpath hosting', async () => {
    const bundle = await buildSiteBundle(createSite({ baseUrl: 'https://user.github.io/repo' }));

    const doc = dom(bundle['404.html'] as string);
    expect(doc.querySelector('link[rel="stylesheet"]')?.getAttribute('href')).toBe('/repo/_site/themes/starter/styles.css');
    expect(Array.from(doc.querySelectorAll('nav a')).map((a) => a.getAttribute('href'))).toEqual([
      '/repo/index.html',
      '/repo/about/index.html',
    ]);
    expect(doc.querySelector('main a')?.getAttribute('href')).toBe('/repo/');
  });

  test('works without a baseUrl, rooted at /', async () => {
    const bundle = await buildSiteBundle(createSite());

    const doc = dom(bundle['404.html'] as string);
    expect(doc.querySelector('link[rel="stylesheet"]')?.getAttribute('href')).toBe('/_site/themes/starter/styles.css');
  });

  test('uses the published page with slug 404 instead of the default, still noindex', async () => {
    const custom = page('content/404.md', 'Lost in space', {}, 'Custom missing page copy');
    const bundle = await buildSiteBundle(createSite({ baseUrl: 'https://user.github.io/repo', files: [custom] }));

    const html = bundle['404.html'] as string;
    const doc = dom(html);
    expect(doc.querySelector('title')?.textContent).toBe('Lost in space');
    expect(html).toContain('Custom missing page copy');
    expect(html).not.toContain('does not exist or has moved');
    expect(doc.querySelector('link[rel="stylesheet"]')?.getAttribute('href')).toBe('/repo/_site/themes/starter/styles.css');
    expect(doc.querySelector('meta[name="robots"]')?.getAttribute('content')).toBe('noindex');

    // The page's own address is not indexed either.
    const own = dom(bundle['404/index.html'] as string);
    expect(own.querySelector('meta[name="robots"]')?.getAttribute('content')).toBe('noindex');
    expect(bundle['sitemap.xml']).not.toContain('/404');
  });

  test('ignores an unpublished 404 page and falls back to the default', async () => {
    const draft = page('content/404.md', 'Draft 404', { published: false }, 'Secret draft copy');
    const bundle = await buildSiteBundle(createSite({ files: [draft] }));

    const html = bundle['404.html'] as string;
    expect(html).not.toContain('Secret draft copy');
    expect(dom(html).querySelector('title')?.textContent).toBe('Page not found');
  });
});

describe('redirects', () => {
  const moved = (extra: Record<string, unknown>) => page('content/blog/new-home.md', 'New home', extra);

  test('emits a Netlify _redirects line and an HTML stub at each nested old path', async () => {
    const bundle = await buildSiteBundle(
      createSite({
        baseUrl: 'https://example.org',
        files: [moved({ redirect_from: ['/old/deeply/nested/post', '/legacy.html'] })],
      }),
    );

    expect(bundle['_redirects']).toBe(
      '/old/deeply/nested/post /blog/new-home 301\n/legacy.html /blog/new-home 301\n',
    );

    for (const path of ['old/deeply/nested/post/index.html', 'legacy.html']) {
      const doc = dom(bundle[path] as string);
      expect(doc.querySelector('meta[http-equiv="refresh"]')?.getAttribute('content')).toBe(
        '0; url=https://example.org/blog/new-home',
      );
      expect(doc.querySelector('link[rel="canonical"]')?.getAttribute('href')).toBe('https://example.org/blog/new-home');
      expect(doc.querySelector('a')?.getAttribute('href')).toBe('https://example.org/blog/new-home');
    }
  });

  test('keeps the hosting subpath in targets', async () => {
    const bundle = await buildSiteBundle(
      createSite({ baseUrl: 'https://user.github.io/repo', files: [moved({ redirect_from: ['/old'] })] }),
    );

    expect(bundle['_redirects']).toBe('/old /repo/blog/new-home 301\n');
    const doc = dom(bundle['old/index.html'] as string);
    expect(doc.querySelector('meta[http-equiv="refresh"]')?.getAttribute('content')).toBe(
      '0; url=https://user.github.io/repo/blog/new-home',
    );
  });

  test('without a baseUrl the stub refreshes to a root path and has no canonical link', async () => {
    const bundle = await buildSiteBundle(createSite({ files: [moved({ redirect_from: ['/old'] })] }));

    const doc = dom(bundle['old/index.html'] as string);
    expect(doc.querySelector('meta[http-equiv="refresh"]')?.getAttribute('content')).toBe('0; url=/blog/new-home');
    expect(doc.querySelector('link[rel="canonical"]')).toBeNull();
  });

  test('redirecting to the homepage targets the site root', async () => {
    const home = page('content/home.md', 'Home', { homepage: true, redirect_from: ['/start'] });
    const site = createSite({ baseUrl: 'https://example.org' });
    site.contentFiles![0] = home;

    const bundle = await buildSiteBundle(site);

    expect(bundle['_redirects']).toBe('/start / 301\n');
    expect(dom(bundle['start/index.html'] as string).querySelector('meta[http-equiv="refresh"]')?.getAttribute('content')).toBe(
      '0; url=https://example.org/',
    );
  });

  test('never overwrites a real page, and drops redirects that loop back to their own page', async () => {
    const bundle = await buildSiteBundle(
      createSite({
        baseUrl: 'https://example.org',
        files: [moved({ redirect_from: ['/about', '/blog/new-home', '/ok'] })],
      }),
    );

    expect(bundle['about/index.html']).toContain('About body');
    expect(bundle['about/index.html']).not.toContain('http-equiv="refresh"');
    expect(bundle['blog/new-home/index.html']).toContain('New home body');
    expect(bundle['_redirects']).toBe('/ok /blog/new-home 301\n');
  });

  test('gives a path two pages claim to the first one', async () => {
    const other = page('content/other.md', 'Other', { redirect_from: ['/old'] });
    const bundle = await buildSiteBundle(createSite({ files: [moved({ redirect_from: ['/old'] }), other] }));

    expect(bundle['_redirects']).toBe('/old /blog/new-home 301\n');
  });

  test('creates nothing for an unpublished page, and no _redirects file when there are no redirects', async () => {
    const draft = moved({ published: false, redirect_from: ['/old'] });
    const bundle = await buildSiteBundle(createSite({ files: [draft] }));

    expect(bundle['old/index.html']).toBeUndefined();
    expect(bundle['_redirects']).toBeUndefined();
  });

  test('escapes markup in a hostile old path', async () => {
    const bundle = await buildSiteBundle(
      createSite({ files: [moved({ redirect_from: ['/x"><script>alert(1)</script>'] })] }),
    );

    const stubs = Object.entries(bundle).filter(([path]) => path.startsWith('x'));
    expect(stubs).toHaveLength(1);
    expect(stubs[0][1] as string).not.toContain('<script>');
  });
});
